#!/bin/sh
# Test media for the examples, generated by FFmpeg itself (nothing to download).
set -e
mkdir -p media out
gen() {
  ffmpeg -hide_banner -v error -y -f lavfi -i "$1" -f lavfi -i "$2" -t "$3" \
    -c:v libx264 -preset veryfast -pix_fmt yuv420p -c:a aac -b:a 192k -shortest "media/$4"
}
gen testsrc2=size=1280x720:rate=30 sine=frequency=440:sample_rate=48000 10 short.mp4
gen testsrc2=size=1280x720:rate=30 sine=frequency=440:sample_rate=48000 600 long.mp4
gen testsrc2=size=1920x1080:rate=30 sine=frequency=440:sample_rate=48000 60 minute.mp4
gen testsrc2=size=1920x1080:rate=30000/1001 \
    "sine=frequency=1000:sample_rate=44100,aformat=channel_layouts=stereo" 5 ntsc.mov
gen testsrc2=size=1280x720:rate=30 \
    "sine=frequency=220:sample_rate=48000,tremolo=f=0.4:d=0.6,volume=-6dB" 60 tone.mp4
gen testsrc2=size=1280x720:rate=30 \
    "anoisesrc=color=pink:amplitude=0.1:sample_rate=48000:seed=7,tremolo=f=0.4:d=0.8" 60 noise.mp4
for i in 1 2 3 4 5 6 7 8; do
  gen "testsrc2=size=1920x1080:rate=30,hue=h=$((i * 40))" \
      "sine=frequency=$((300 + i * 50)):sample_rate=48000" 20 "clip$i.mp4"
done
